import { recipe } from '../detail-helpers-v1.js';
import { orderProse } from '../social/order-prose.js';
const provided='{supplier} at {fromPlace} provided {item} for {buyer}.|{buyer} at {toPlace} received {item} from {supplier} at {fromPlace}.|{supplier} at {fromPlace} supplied {buyer} with {item}.|The request for {item} from {buyer} was completed by {supplier} at {fromPlace}.|{buyer} has received {item} from {supplier} at {fromPlace}.|{supplier} at {fromPlace} completed {buyer}’s request for {item}.|The request from {buyer} at {toPlace} for {item} has been fulfilled by {supplier}.|{supplier} at {fromPlace} fulfilled {buyer}’s request for {item}.|{buyer} at {toPlace} has received the requested {productName} from {supplier}.|{supplier} at {fromPlace} has provided the requested {productName} to {buyer}.';
const bookings='{supplier} and {buyer} have different times written down for {item} at {fromPlace}.|The booking notes held by {supplier} and {buyer} give different times for {item} at {fromPlace}.|{buyer} and {supplier} expect {item} at {fromPlace} at different times.|{supplier}’s and {buyer}’s notes disagree about the time for {item} at {fromPlace}.|{supplier} and {buyer} have conflicting times for {item} at {fromPlace}.|{buyer} has a different time from {supplier} for {item} at {fromPlace}.|The time for {item} at {fromPlace} differs between {supplier}’s and {buyer}’s notes.|{supplier} and {buyer} disagree about the booked time for {item} at {fromPlace}.|The booking for {item} at {fromPlace} gives {supplier} and {buyer} conflicting times.|{supplier} and {buyer} have different booking times for {item} at {fromPlace}.';
const bookingGoals='compare the two booking notes|take the available times from {supplier} to {buyer}|bring the confirmed time to {fromPlace}|check which booking time was changed|ask both parties to agree a new time|find the message about the changed booking|take the revised time to {toPlace}|ask who arranged the booking|bring the agreed time to both parties|confirm where the booking will take place';
export const serviceStorySources={story_invoice:recipe(provided,orderProse.invoice.ends),story_appointment:recipe(bookings,orderProse.appointment.ends),goal_appointment:recipe(bookingGoals,orderProse.appointment.followups,', then ')};
export function serviceStorySource(key,context) {
  return key==='request'?directRequests:context.workflow==='service'?serviceStorySources[key]:null;
}

const requestPlaces='At {fromPlace},|In {fromDistrict},|For the job at {fromPlace},|For the work at {fromPlace},|To help at {fromPlace},|For this job,|For this request,|For this work,|To help with this,|For follow-up,';
export const directRequests=recipe(requestPlaces,'{requester} asks you to {goal}.|{requester} wants you to {goal}.|{requester} needs you to {goal}.|{requester} would like you to {goal}.|{requester} is asking you to {goal}.|{requester} has asked you to {goal}.|{requester} invites you to {goal}.|{requester} requests that you {goal}.|{requester} hopes you will {goal}.|{requester} is looking for a volunteer to {goal}.');
